rss.channel:
    {{ title }} | {{ languages[lang].language }}
    {{ lang_url }}

    {{ title }} - {{ languages[lang].language }}
    {{ lang }}
{%- if items %}
    {{ items[0][1].last|rfc822 }}
{%- endif %}
{%- for section, topic in items %}


      {{ section.title }} / {{ topic.title }}
      {{ lang_url }}/{{ section.path }}/{{ topic.path }}
      {{ lang_url }}/{{ section.path }}/{{ topic.path }}
      {{ topic.last|rfc822 }}
      {{ topic.user_name }}
      {{ section.title }}: {{ topic.count }} posts, last by {{ topic.user_name }}

{%- endfor %}
